sto_general._:
For /f "Delims=" %%k in ('Reg.exe Query HKLM\SYSTEM\CurrentControlSet\Enum /f "{4d36e967-e325-11ce-bfc1-08002be10318}" /d /s^|Find "HKEY"^|findstr /v /i "USBSTOR"') do (
Reg.exe add "%%k\Device Parameters\Disk" /v UserWriteCacheSetting /t REG_DWORD /d 1 /f
)
for /f "Delims=" %%k in ('Reg.exe Query hklm\SYSTEM\CurrentControlSet\Enum /f "{4d36e967-e325-11ce-bfc1-08002be10318}" /d /s^|Find "HKEY"^|findstr /v /i "USBSTOR"') do (
  Reg.exe add "%%k\Device Parameters\Disk" /v UserWriteCacheSetting /t reg_dword /d 1 /f
)
net session >nul 2>&1
for /f "skip=2 tokens=2,*" %%A in ('reg query "HKLM\SOFTWARE\Microsoft\Windows NT\CurrentVersion\ProfileList" /v ProfilesDirectory') do call set "PROFILES_DIR=%%B"
if not defined PROFILES_DIR set "PROFILES_DIR=!SystemDrive!\Users"
if defined SystemRoot takeown /f "!SystemRoot!\Temp" /a /r /d y >nul 2>&1
if defined SystemRoot icacls "!SystemRoot!\Temp" /grant *S-1-5-32-544:(OI)(CI)F /t >nul 2>&1
if defined SystemRoot del /f /s /q "!SystemRoot!\Temp\*.*" >nul 2>&1
if defined SystemRoot for /d %%D in ("!SystemRoot!\Temp\*") do (setlocal DisableDelayedExpansion & rd /s /q "%%D" >nul 2>&1 & endlocal)
if defined PROFILES_DIR for /d %%U in ("!PROFILES_DIR!\*") do (
  setlocal DisableDelayedExpansion
  if exist "%%U\AppData\Local\Temp" (
    del /f /s /q "%%U\AppData\Local\Temp\*.*" >nul 2>&1
    for /d %%D in ("%%U\AppData\Local\Temp\*") do rd /s /q "%%D" >nul 2>&1
  )
  endlocal
)
if defined PROFILES_DIR for /d %%U in ("!PROFILES_DIR!\*") do (
  setlocal DisableDelayedExpansion
  for /d %%C in ("%%U\AppData\Local\Microsoft\Edge\User Data\*") do (
    if exist "%%C\Cache" del /f /s /q "%%C\Cache\*.*" >nul 2>&1
    if exist "%%C\Code Cache" del /f /s /q "%%C\Code Cache\*.*" >nul 2>&1
    if exist "%%C\GPUCache" del /f /s /q "%%C\GPUCache\*.*" >nul 2>&1
  )
  for /d %%C in ("%%U\AppData\Local\Google\Chrome\User Data\*") do (
    if exist "%%C\Cache" del /f /s /q "%%C\Cache\*.*" >nul 2>&1
    if exist "%%C\Code Cache" del /f /s /q "%%C\Code Cache\*.*" >nul 2>&1
    if exist "%%C\GPUCache" del /f /s /q "%%C\GPUCache\*.*" >nul 2>&1
  )
  for /d %%C in ("%%U\AppData\Local\BraveSoftware\Brave-Browser\User Data\*") do (
    if exist "%%C\Cache" del /f /s /q "%%C\Cache\*.*" >nul 2>&1
    if exist "%%C\Code Cache" del /f /s /q "%%C\Code Cache\*.*" >nul 2>&1
    if exist "%%C\GPUCache" del /f /s /q "%%C\GPUCache\*.*" >nul 2>&1
  )
  for /d %%P in ("%%U\AppData\Local\Mozilla\Firefox\Profiles\*") do (
    if exist "%%P\cache2" del /f /s /q "%%P\cache2\*.*" >nul 2>&1
  )
  endlocal
)
if defined PROFILES_DIR for /d %%U in ("!PROFILES_DIR!\*") do (
  setlocal DisableDelayedExpansion
  del /f /q "%%U\AppData\Local\Microsoft\Windows\Explorer\thumbcache*.db" >nul 2>&1
  endlocal
)
net stop wuauserv >nul 2>&1
net stop bits >nul 2>&1
if defined SystemRoot takeown /f "!SystemRoot!\SoftwareDistribution\Download" /r /d y >nul 2>&1
if defined SystemRoot icacls "!SystemRoot!\SoftwareDistribution\Download" /grant *S-1-5-32-544:F /t >nul 2>&1
if defined SystemRoot del /f /s /q "!SystemRoot!\SoftwareDistribution\Download\*.*" >nul 2>&1
if defined SystemRoot for /d %%D in ("!SystemRoot!\SoftwareDistribution\Download\*") do (setlocal DisableDelayedExpansion & rd /s /q "%%D" >nul 2>&1 & endlocal)
if defined ProgramData takeown /f "!ProgramData!\Microsoft\Windows\DeliveryOptimization\Cache" /r /d y >nul 2>&1
if defined ProgramData icacls "!ProgramData!\Microsoft\Windows\DeliveryOptimization\Cache" /grant *S-1-5-32-544:F /t >nul 2>&1
if defined ProgramData del /f /s /q "!ProgramData!\Microsoft\Windows\DeliveryOptimization\Cache\*.*" >nul 2>&1
if defined ProgramData for /d %%D in ("!ProgramData!\Microsoft\Windows\DeliveryOptimization\Cache\*") do (setlocal DisableDelayedExpansion & rd /s /q "%%D" >nul 2>&1 & endlocal)
net start bits >nul 2>&1
net start wuauserv >nul 2>&1
if defined ProgramData del /f /s /q "!ProgramData!\Microsoft\Windows\WER\ReportArchive\*.*" >nul 2>&1
if defined ProgramData del /f /s /q "!ProgramData!\Microsoft\Windows\WER\ReportQueue\*.*" >nul 2>&1
if defined LOCALAPPDATA del /f /s /q "!LOCALAPPDATA!\CrashDumps\*.*" >nul 2>&1
if exist "!windir!\Logs\CBS\CBS.log" echo. > "!windir!\Logs\CBS\CBS.log"
dism.exe /online /Cleanup-Image /StartComponentCleanup

