net_msi._:
for /f %%i in ('powershell -NoProfile -Command "(Get-CimInstance win32_NetworkAdapter).PNPDeviceID"') do set "str=%%i" & (
echo. Delete network Device Priority 
reg delete "HKLM\System\CurrentControlSet\Enum\%%i\Device Parameters\Interrupt Management\Affinity Policy" /v "DevicePriority" /f >nul 2>&1
echo. Enable MSI Mode on NetAdapter 
Reg.exe add "HKLM\System\CurrentControlSet\Enum\%%i\Device Parameters\Interrupt Management\MessageSignaledInterruptProperties" /v "MSISupported" /t REG_DWORD /d "1" /f
)

net_restart._:
echo Restarting network adapter...
PowerShell.exe -Command "Get-NetAdapter | Where-Object { $_.Status -eq 'Up' } | Restart-NetAdapter" >nul 2>&1
if %ERRORLEVEL% NEQ 0 (
    echo Error restarting network adapter.
    exit /b 0
)
if defined dns_applied (
    echo %dns_applied% settings applied successfully.
)

