cln_temp._:
echo - Cleaning C:\Windows\Temp
if exist "C:\Windows\Temp" (
    cd /d "C:\Windows\Temp" && for /F "delims=" %%i in ('dir /b') do (setlocal DisableDelayedExpansion & (rmdir "%%i" /s/q 2>nul || del "%%i" /s/q 2>nul) & endlocal)
)
echo - Cleaning !TEMP!
if defined LOCALAPPDATA if exist "!LOCALAPPDATA!\Temp" (
    cd /d "!LOCALAPPDATA!\Temp" && for /F "delims=" %%i in ('dir /b') do (setlocal DisableDelayedExpansion & (rmdir "%%i" /s/q 2>nul || del "%%i" /s/q 2>nul) & endlocal)
)

cln_devices._:
echo  -  Cleaning Useless Device Data...
@echo on
POWERSHELL "$Devices = Get-PnpDevice | ? Status -eq Unknown;foreach ($Device in $Devices) { &\"pnputil\" /remove-device $Device.InstanceId }"
@echo off

exp_iolatency._:
echo - Disabling IO Latency Cap: 
FOR /F "eol=E" %%a in ('REG QUERY "HKLM\System\CurrentControlSet\Services" /S /F "IoLatencyCap"^| FINDSTR /V "IoLatencyCap"') DO (
Reg.exe add "%%a" /v "IoLatencyCap" /t REG_DWORD /d "0" /f
FOR /F "tokens=*" %%z IN ("%%a") DO (
SET STR=%%z
SET STR=!STR:HKLM\System\CurrentControlSet\services\=!
SET STR=!STR:\Parameters=!
)
)
